<template>
  <view class="student-page">
    <view class="safe-area" />
    <view class="page-top forum-hero"><view><text class="eyebrow">问答广场</text><text class="page-title">看看真实的校园讨论</text><text class="intro">高中生和大学生都可以参与公开回复。</text></view></view>
    <view class="tabs forum-tabs"><text v-for="tab in tabs" :key="tab.key" :class="{ active: active === tab.key }" @tap="active = tab.key">{{ tab.label }}</text></view>
    <view v-if="active === 'campus'" class="campus-filter"><view class="campus-search"><text class="campus-search-icon">⌕</text><input v-model="schoolSearch" class="campus-search-input" placeholder="搜索大学论坛" confirm-type="search" /></view><view class="campus-chips"><text v-for="school in filteredCampuses" :key="school" :class="{ active: campus === school }" @tap="campus = school">{{ school }}</text></view></view>
    <view class="composer forum-ask" @tap="openComposer"><view><text class="composer-title">想加入讨论？</text><text class="composer-subtitle">发一条公开帖子，让大家一起回复。</text><text class="forum-post-link">＋ 发布帖子</text></view></view>
    <view class="post-list forum-post-list"><view v-for="post in visiblePosts" :key="post.id" class="post forum-post" @tap="openPost(post)" @longpress="openPostReport(post)"><view class="post-head forum-post-meta"><view class="post-author"><text class="author-name">{{ post.author }}</text><text class="identity-badge" :class="roleClass(post.role)">{{ post.role }}</text><text class="forum-school">{{ post.school }}</text></view><text class="favorite" :class="{ saved: saved.has(post.id) }" @tap.stop="toggleSave(post)">{{ saved.has(post.id) ? '★' : '☆' }}</text></view><text class="post-title forum-topic">{{ post.title }}</text><view class="post-footer forum-foot"><text class="post-meta">{{ post.time }}</text><view class="forum-actions"><text>{{ post.comments }} 条讨论</text><text>回复</text></view></view></view><view v-if="!visiblePosts.length" class="empty">这个分区还没有内容</view></view>
    <view v-if="composer" class="mask" @tap="closeComposer"><view class="sheet" @tap.stop><view class="sheet-head"><text class="sheet-title">发布公开帖子</text><button class="sheet-close" @tap="closeComposer">关闭</button></view><view class="compose-identity"><text class="identity-label">发帖身份</text><text class="identity-badge" :class="roleClass(activeIdentityLabel)">{{ activeIdentityLabel }}</text></view><UniversitySearch v-if="identityType === 'student'" :selected-id="selectedUniversity?.id" :selected-name="selectedUniversity?.name" :z-index="2200" placeholder="请选择关联大学" @select="onUniversitySelect" /><input v-model="draftTitle" class="compose-input" placeholder="写一个清晰的标题" /><textarea v-model="draftBody" class="compose-textarea" placeholder="分享你的问题或经验" /><button class="primary-button" @tap="submitPost">发布帖子</button></view></view>

    <view v-if="detailPost" class="discussion-page"><view class="discussion-safe-top" /><view class="discussion-head"><button class="discussion-back" @tap="closeDetail">返回</button><text class="discussion-heading">讨论详情</text><view class="discussion-spacer" /></view><scroll-view scroll-y class="discussion-content"><view class="discussion-post"><view class="discussion-author-line"><view class="discussion-avatar">{{ initial(detailPost.author) }}</view><view><text class="discussion-author">{{ detailPost.author }}</text><view class="author-meta"><text class="identity-badge" :class="roleClass(detailPost.role)">{{ detailPost.role }}</text><text>{{ detailPost.school || '校园社区' }}</text><text class="post-time">{{ detailPost.time }}</text></view></view></view><text class="discussion-title">{{ detailPost.title }}</text><text class="discussion-copy">{{ detailPost.body }}</text><view class="discussion-actions"><button class="discussion-action" :class="{ saved: detailPost.liked }" @tap="togglePostLike">♡ {{ detailPost.likes || 0 }}</button><button class="discussion-action" :class="{ saved: saved.has(detailPost.id) }" @tap="toggleSave(detailPost)">{{ saved.has(detailPost.id) ? '已收藏' : '收藏' }}</button><button class="discussion-action" @tap="openDetailReport">🚩 举报</button></view></view><view class="discussion-section-head"><text>全部评论 {{ comments.length }}</text></view><view v-if="comments.length" class="discussion-comments"><view v-for="comment in topLevelComments" :key="comment.id" class="comment-thread"><view class="comment-row" @longpress="openCommentReport(comment)"><view class="comment-avatar">{{ initial(commentName(comment)) }}</view><view class="comment-main"><view class="comment-author-line"><text class="comment-author">{{ commentName(comment) }}</text><text class="identity-badge" :class="roleClass(commentRole(comment))">{{ commentRole(comment) }}</text></view><text class="comment-copy">{{ comment.content || comment.text || '' }}</text><view class="comment-foot"><text class="comment-meta">{{ comment.createdAt || comment.time || '刚刚' }}</text><text class="comment-action" @tap="replyTo(comment)">回复</text><text class="comment-action" @tap="openCommentReport(comment)">举报</text><text class="like-action" :class="{ liked: comment.liked }" @tap.stop="likeComment(comment)">♡ {{ comment.likeCount || comment.likes || 0 }}</text></view></view></view><view v-if="repliesOf(comment).length" class="reply-summary" @tap="toggleReplies(comment.id)"><view class="reply-line" /><text>{{ expandedReplies[comment.id] ? '收起' : '展开' }} {{ repliesOf(comment).length }} 条回复</text><text class="reply-chevron">⌄</text></view><view v-if="expandedReplies[comment.id]" class="nested-comments"><view v-for="reply in repliesOf(comment)" :key="reply.id" class="comment-row" @longpress="openCommentReport(reply)"><view class="comment-avatar reply-avatar">{{ initial(commentName(reply)) }}</view><view class="comment-main"><view class="comment-author-line"><text class="comment-author">{{ commentName(reply) }}</text><text class="identity-badge" :class="roleClass(commentRole(reply))">{{ commentRole(reply) }}</text></view><text class="comment-copy"><text class="reply-prefix">回复 @{{ commentName(comment) }}：</text>{{ reply.content || reply.text || '' }}</text><view class="comment-foot"><text class="comment-meta">{{ reply.createdAt || reply.time || '刚刚' }}</text><text class="comment-action" @tap="replyTo(reply)">回复</text><text class="comment-action" @tap="openCommentReport(reply)">举报</text><text class="like-action" :class="{ liked: reply.liked }" @tap.stop="likeComment(reply)">♡ {{ reply.likeCount || reply.likes || 0 }}</text></view></view></view></view></view></view><view v-else class="discussion-empty">暂时还没有评论，来发表第一条回复。</view></scroll-view><view class="reply-bar"><view v-if="replyTarget" class="reply-target"><text>回复 @{{ commentName(replyTarget) }}</text><text class="reply-cancel" @tap="replyTarget = null">取消</text></view><view class="identity-picker"><text class="identity-label">本次发言身份</text><text class="identity-badge" :class="roleClass(activeIdentityLabel)">{{ activeIdentityLabel }}</text></view><view class="reply-row"><input v-model="replyContent" class="reply-input" :placeholder="replyTarget ? '写下你的回复' : '友善交流，留下你的想法'" /><button class="reply-button" @tap="submitReply">发送</button></view></view></view>

    <view v-if="reportTarget" class="report-mask" @tap="reportTarget = null"><view class="report-sheet" @tap.stop><view class="sheet-head"><text class="sheet-title">{{ reportTarget.type === 'comment' ? '举报评论' : '举报帖子' }}</text><button class="sheet-close" @tap="reportTarget = null">关闭</button></view><text class="report-hint">请选择举报原因，提交后将交由社区审核。</text><view class="report-reasons"><text v-for="reason in reportReasons" :key="reason" class="report-reason" :class="{ active: reportReason === reason }" @tap="reportReason = reason">{{ reason }}</text></view><textarea v-model="reportDetail" class="report-textarea" placeholder="可补充具体情况（选填）" /><button class="danger-button" @tap="submitReport">提交举报</button></view></view>
    <TabBar v-if="!detailPost" currentPath="/pages/student/qa-forum" />
  </view>
</template>

<script setup>
import { computed, ref, watch } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import { useUserStore } from '@/store/modules/user'
import TabBar from '@/components/TabBar.vue'
import UniversitySearch from '@/components/UniversitySearch.vue'
import * as qaApi from '@/api/qa'
import * as commentApi from '@/api/comment'
import * as forumApi from '@/api/forum'
import * as studentApi from '@/api/student'

const scopes = [{ key: 'school', label: '本校' }, { key: 'all', label: '总论坛' }]
const topics = ['全部', '推荐', '专业选择', '校园生活', '志愿填报']
const tabs = [{ key: 'saved', label: '收藏' }, { key: 'student', label: '高中生说' }, { key: 'university', label: '大学生说' }, { key: 'campus', label: '大学论坛' }]
const reportReasons = ['不当言论', '虚假信息', '广告骚扰', '其他']
const props = defineProps({ detailId: { type: [String, Number], default: '' } })
const userStore = useUserStore()
const scope = ref('all'); const topic = ref('全部'); const active = ref('saved'); const campus = ref('全部高校'); const schoolSearch = ref(''); const unread = ref(false); const posts = ref([]); const saved = ref(new Set()); const comments = ref([]); const mySchool = ref('')
const detailPost = ref(null); const composer = ref(false); const draftTitle = ref(''); const draftBody = ref(''); const selectedUniversity = ref(null); const replyContent = ref(''); const replyTarget = ref(null); const expandedReplies = ref({}); const reportTarget = ref(null); const reportReason = ref(reportReasons[0]); const reportDetail = ref('')
// 身份以当前微信身份为准。userInfo.userType 是后端 JWT 的来源，优先于
// 可能残留的 userRole，避免志愿者切回高中生页面后被错误显示成高中生。
const identityType = computed(() => {
  const infoType = String(userStore.userInfo?.userType || '').toLowerCase()
  if (infoType === 'volunteer' || infoType === 'student') return infoType
  const role = String(userStore.userRole || '').toLowerCase()
  return role === 'volunteer' || role === 'student' ? role : ''
})
const activeIdentity = computed(() => identityType.value === 'volunteer' ? '志愿者' : identityType.value === 'student' ? '高中生' : '')
const activeIdentityLabel = computed(() => activeIdentity.value || '未认证')
const campuses = computed(() => ['全部高校', ...new Set(posts.value.map(post => post.school).filter(Boolean))])
const filteredCampuses = computed(() => { const keyword = schoolSearch.value.trim().toLowerCase(); return campuses.value.filter(school => school === '全部高校' || !keyword || school.toLowerCase().includes(keyword)) })
// 收藏 tab 属于个人内容不参与范围过滤；本校 = 与本人生源高中相同的帖子
const visiblePosts = computed(() => posts.value.filter(post =>
  (active.value === 'saved' || scope.value === 'all' || !mySchool.value || post.school === mySchool.value) &&
  (active.value === 'saved' ? saved.value.has(post.id) : active.value === 'campus' ? post.kind === 'campus' && (campus.value === '全部高校' || post.school === campus.value) : post.kind === active.value)))
const topLevelComments = computed(() => comments.value.filter(comment => !comment.parentId && !comment.parentCommentId))
onShow(loadForum)
watch(() => props.detailId, id => { if (id) openPost({ id: Number(id) }) }, { immediate: true })
function rows(result) { return result?.records || result?.data?.records || result?.data || result || [] }
function flattenComments(items) { const output = []; const visit = list => (Array.isArray(list) ? list : []).forEach(item => { const { children, ...comment } = item || {}; output.push(comment); visit(children) }); visit(items); return output }
function initial(value) { return String(value || '匿').slice(0, 1) }
function truncate(value, max) { const text = String(value || ''); return text.length > max ? `${text.slice(0, max)}...` : text }
function roleClass(role) { return role === '大学生' ? 'role-university' : role === '志愿者' ? 'role-volunteer' : 'role-student' }
function commentName(comment) { return comment.authorName || comment.userName || comment.nickname || comment.author || '匿名用户' }
function displayRole(value) { const key = String(value || '').toLowerCase(); return key === 'volunteer' || key === '志愿者' ? '志愿者' : key === 'university' || key === 'university_student' || key === '大学生' ? '大学生' : key === 'forum' || key === 'campus' || key === '大学论坛' ? '大学论坛' : key === 'student' || key === 'high_school_student' || key === '高中生' ? '高中生' : '身份待确认' }
function commentRole(comment) { return displayRole(comment.identityLabel || comment.authorType || comment.userType || comment.role) }
function normalize(item) { const rawRole = item.authorType || item.authorRole || item.userType || item.role; const role = displayRole(rawRole); const rawKind = String(rawRole || '').toLowerCase(); const kind = rawKind === 'forum' || rawKind === 'campus' || role === '大学论坛' ? 'campus' : role === '大学生' || role === '志愿者' ? 'university' : 'student'; return { id: item.id || item.qaId || item.postId, author: item.authorName || item.askerName || item.userName || '匿名用户', role, school: item.askerHighSchool || item.highSchoolName || item.universityName || item.schoolName || '', title: item.title || item.questionTitle || item.question || '未命名帖子', body: item.questionContent || item.content || item.summary || '', time: item.askedAt || item.createdAt || item.time || '', comments: item.commentCount || item.answerCount || 0, likes: item.likeCount || 0, liked: Boolean(item.liked), category: item.categoryName || item.category || '全部', scope: item.scope || (item.universityId ? 'school' : 'all'), kind } }
async function loadForum() { try { posts.value = rows(await qaApi.getForumPosts({ page: 1, size: 30 })).map(normalize).filter(item => item.id) } catch (error) { posts.value = [] } try { const info = await studentApi.getMyInfo(); mySchool.value = info?.highSchoolName || '' } catch (error) { mySchool.value = '' } try { saved.value = new Set(rows(await qaApi.getMyFavorites({ page: 1, size: 100 })).map(item => item.id || item.qaId || item.postId).filter(Boolean)) } catch (error) { saved.value = new Set() } }
function go(url) { uni.navigateTo({ url }) }
async function toggleSave(post) { try { await qaApi.toggleFavorite(post.id); const next = new Set(saved.value); next.has(post.id) ? next.delete(post.id) : next.add(post.id); saved.value = next } catch (error) { uni.showToast({ title: '收藏操作失败', icon: 'none' }) } }
async function openComposer() { if (!identityType.value || !userStore.hasBoundIdentity) return uni.showToast({ title: '请先完成身份认证', icon: 'none' }); composer.value = true }
function closeComposer() { composer.value = false; draftTitle.value = ''; draftBody.value = ''; selectedUniversity.value = null }
function onUniversitySelect(university) { selectedUniversity.value = university }
async function submitPost() { if (!identityType.value || !userStore.hasBoundIdentity) return uni.showToast({ title: '请先完成身份认证', icon: 'none' }); if (identityType.value === 'student' && !selectedUniversity.value) return uni.showToast({ title: '请选择关联大学', icon: 'none' }); if (!draftTitle.value.trim() || !draftBody.value.trim()) return uni.showToast({ title: '请填写标题和内容', icon: 'none' }); try { const categoryMap = { '专业选择': 'major', '校园生活': 'campus', '志愿填报': 'admission', '推荐': 'other', '全部': 'other' }; await qaApi.submitQuestion({ title: draftTitle.value.trim(), questionContent: draftBody.value.trim(), category: categoryMap[topic.value] || 'other', targetVolunteerId: null, universityId: identityType.value === 'volunteer' ? userStore.userInfo?.universityId || null : selectedUniversity.value?.id || null }); composer.value = false; draftTitle.value = ''; draftBody.value = ''; selectedUniversity.value = null; await loadForum(); uni.showToast({ title: '已提交，审核通过后展示', icon: 'none' }) } catch (error) { uni.showToast({ title: error?.message || '发布失败', icon: 'none', duration: 2500 }) } }
async function openPost(post) { detailPost.value = post; comments.value = []; expandedReplies.value = {}; try { const detail = await qaApi.getQADetail(post.id); detailPost.value = { ...post, ...normalize(detail?.data || detail) } } catch (error) {} try { comments.value = flattenComments(rows(await commentApi.getComments(post.id))) } catch (error) { comments.value = [] } }
function closeDetail() { detailPost.value = null; replyTarget.value = null; replyContent.value = ''; if (props.detailId) uni.navigateBack() }
function repliesOf(comment) { return comments.value.filter(item => String(item.parentId || item.parentCommentId || '') === String(comment.id)) }
function toggleReplies(id) { expandedReplies.value = { ...expandedReplies.value, [id]: !expandedReplies.value[id] } }
function replyTo(comment) { replyTarget.value = comment }
async function submitReply() { if (!identityType.value || !userStore.hasBoundIdentity) return uni.showToast({ title: '请先完成身份认证', icon: 'none' }); if (!detailPost.value || !replyContent.value.trim()) return uni.showToast({ title: '请输入回复内容', icon: 'none' }); try { await commentApi.addComment({ postId: Number(detailPost.value.id), content: replyContent.value.trim(), parentId: replyTarget.value?.id ? Number(replyTarget.value.id) : null }); replyContent.value = ''; replyTarget.value = null; comments.value = flattenComments(rows(await commentApi.getComments(detailPost.value.id))) } catch (error) { uni.showToast({ title: error?.message || '回复失败', icon: 'none', duration: 2500 }) } }
async function likeComment(comment) { try { await commentApi.toggleCommentLike(comment.id); comments.value = flattenComments(rows(await commentApi.getComments(detailPost.value.id))) } catch (error) { uni.showToast({ title: error?.message || '点赞失败', icon: 'none' }) } }
async function togglePostLike() { if (!detailPost.value) return; try { await qaApi.toggleLike(detailPost.value.id); detailPost.value = { ...detailPost.value, liked: !detailPost.value.liked, likes: Number(detailPost.value.likes || 0) + (detailPost.value.liked ? -1 : 1) } } catch (error) { uni.showToast({ title: '点赞失败', icon: 'none' }) } }
function openPostReport(post) { reportTarget.value = { type: 'post', post }; reportReason.value = reportReasons[0]; reportDetail.value = '' }
// 详情页内的帖子举报入口（列表长按举报在详情页不可用）
function openDetailReport() { if (detailPost.value) openPostReport(detailPost.value) }
function openCommentReport(comment) { reportTarget.value = { type: 'comment', comment }; reportReason.value = reportReasons[0]; reportDetail.value = '' }
async function submitReport() { if (!reportTarget.value) return; try { await forumApi.reportPost({ postId: detailPost.value?.id || reportTarget.value.post?.id, targetType: reportTarget.value.type, commentId: reportTarget.value.comment?.id, reason: reportReason.value, detail: reportDetail.value }); reportTarget.value = null; uni.showToast({ title: '举报已提交', icon: 'success' }) } catch (error) { uni.showToast({ title: '举报失败', icon: 'none' }) } }
</script>

<style lang="scss" scoped>
.role-campus{color:#87631a;background:#fff5de}.student-page{padding-bottom:128rpx;background:#f3f7fb;color:#1f2937}.safe-area{height:env(safe-area-inset-top);margin:0 -32rpx}.page-top{padding:30rpx 32rpx 22rpx;align-items:flex-end}.page-title{font-size:42rpx}.notice-label{display:block;width:auto;height:auto;color:#397cba;font-size:22rpx}.intro{display:block;padding:18rpx 0;color:#7b8b99;font-size:24rpx}.tabs{display:flex;gap:30rpx;padding:8rpx 0 18rpx;overflow:hidden}.tabs text{position:relative;padding:10rpx 0;color:#81909d;font-size:25rpx;white-space:nowrap}.tabs text.active{color:#397cba;font-weight:800}.tabs text.active:after{position:absolute;right:0;bottom:0;left:0;height:5rpx;border-radius:99rpx;background:#5b9bd5;content:''}.campus-filter{display:flex;gap:12rpx;padding-bottom:18rpx;overflow:auto}.campus-filter text{padding:11rpx 18rpx;border-radius:999rpx;color:#718394;background:#e8f2f9;font-size:22rpx;white-space:nowrap}.campus-filter text.active{color:#fff;background:#5b9bd5}.scope-filter{display:flex;gap:12rpx;padding:0 32rpx 4rpx}.scope-chip{padding:12rpx 30rpx;border-radius:999rpx;color:#718394;background:#e8f2f9;font-size:24rpx;font-weight:700;white-space:nowrap}.scope-chip.active{color:#fff;background:#397cba}.composer{min-height:0;margin-bottom:22rpx;padding:22rpx;border-radius:20rpx;background:#5b9bd5}.composer-icon{width:auto;height:auto;background:transparent;font-size:36rpx}.composer-title{font-size:27rpx}.composer-subtitle{color:#e7f3ff;font-size:21rpx}.post-list{gap:12rpx}.post{padding:24rpx;border-radius:20rpx}.avatar{width:64rpx;height:64rpx;color:#397cba;background:#dcecf8}.post-author-detail{display:block;margin-top:4rpx;color:#83919e;font-size:21rpx}.post-author-detail .identity-badge{font-size:19rpx;line-height:26rpx;min-height:26rpx}.post-title{margin-top:18rpx;font-size:27rpx;line-height:1.45}.post-meta{display:block;margin-top:10rpx;color:#8998a5;font-size:21rpx}.post-footer{justify-content:flex-start;gap:26rpx;margin-top:15rpx;color